{
  "scenario_title": "Daily property tax assessment appeal counter intake and fee collection across municipal districts, Q3 2023",
  "data_context": "The Assessment Appeals Board Clerk logs each appeal filed at municipal public intake counters during the 2023 annual assessment review window. The registry records property categories, filing stages, statutory intake fees, and assessed valuation under dispute to monitor operational workload and revenue ahead of statutory filing deadlines.",
  "script": "dim(\"district\", [\"Downtown Central\", \"North Metro\", \"South Valley\", \"Harbor West\"], weights=[0.40, 0.28, 0.20, 0.12], group=\"geography\")\ndim(\"property_class\", [\"Single Family Residential\", \"Multi-Family Residential\", \"Commercial & Industrial\", \"Vacant Land\"], weights=[0.52, 0.22, 0.18, 0.08], group=\"property\")\ndim(\"appeal_stage\", [\"Filing Submitted\", \"Fee Verified\", \"Board Docketed\", \"Hearing Resolved\"], weights=[0.44, 0.28, 0.18, 0.10], ordered=\"stage\", group=\"workflow\")\n\ntime(\"intake_date\", start=\"2023-07-01\", end=\"2023-09-30\", freq=\"daily\")\n\nmeasure(\"fee_collected_usd\",\n        \"{\"Single Family Residential\": 45, \"Multi-Family Residential\": 140, \"Commercial & Industrial\": 375, \"Vacant Land\": 60}[property_class] + gaussian(0, 4)\",\n        unit=\"USD\", additive=True)\nmeasure(\"disputed_value_k_usd\",\n        \"{\"Single Family Residential\": 110, \"Multi-Family Residential\": 580, \"Commercial & Industrial\": 2200, \"Vacant Land\": 85}[property_class] * lognormal(0.0, 0.30)\",\n        unit=\"thousand USD\", additive=True)\nmeasure(\"intake_processing_minutes\",\n        \"lognormal(mu = 2.1 + 0.35*[property_class=Commercial & Industrial] + 0.12*[district=Downtown Central], sigma = 0.25)\",\n        unit=\"minutes\", additive=True)\n\nemit(360)\n",
  "intents": [
    {
      "sentence": "Compare total filing fees collected across assessment districts",
      "columns": [
        "district",
        "fee_collected_usd"
      ],
      "aggregate": "SUM",
      "family": "comparison"
    },
    {
      "sentence": "Track average daily intake processing duration over the third quarter appeal window",
      "columns": [
        "intake_date",
        "intake_processing_minutes"
      ],
      "aggregate": "AVG",
      "family": "trend"
    },
    {
      "sentence": "Observe case attrition across progressive stages of the appeal lifecycle",
      "columns": [
        "appeal_stage"
      ],
      "aggregate": "COUNT",
      "family": "process"
    },
    {
      "sentence": "Examine how disputed property valuation relates to statutory filing fees",
      "columns": [
        "disputed_value_k_usd",
        "fee_collected_usd"
      ],
      "aggregate": "NONE",
      "family": "relation"
    }
  ]
}
